{
    "name": "Vietnamese Coffee (Cafe Sua Da)",
    "description": "Vietnamese Iced Coffee is an intensely brewed coffee concentrate that drips down into a tall glass of ice and a big spoonful of sweetened condensed milk.",
    "github": "christinetu",
    "ingredients": [
        {
            "quantity": "2",
            "measure": "tablespoon",
            "ingredient": "French Roast Coffee grinds"
        },
        {
            "quantity": "2",
            "measure": "tablespoon",
            "ingredient": "Sweetened condensed milk"
        },
        {
            "quantity": "1/2",
            "measure": "cup",
            "ingredient": "ice"
        },
        {
            "quantity": "1/4",
            "measure": "cup",
            "ingredient": "water"
        }
    ],
    "directions": [
        "Boil water. Add coffee grounds to phin coffee filter (or pour over coffee filter) and stamp down.",
        "Pour hot water in phin coffee filter (or pour over coffee filter).",
        "Add in Sweetened condensed milk. Stir until well combined.",
        "Add ice and enjoy"
    ],
    "image": "vietnamese-coffee.jpg",
    "keywords": [
        "vietnamese",
        "coffee",
        "non-alcoholic",
        "condensed milk"
    ]
}

{
    "name": "Coconut Coffee",
    "description": "A new Hanoian specialty, where the creaminess of coconut mix perfectly well with the bitter taste of espresso",
    "github": "antran22",
    "ingredients": [
        {
            "quantity": "1",
            "measure": "shot",
            "ingredient": "Espresso"
        },
        {
            "quantity": "50",
            "measure": "ml",
            "ingredient": "Coconut Milk"
        },
        {
            "quantity": "20",
            "measure": "ml",
            "ingredient": "Condensed Milk"
        },
        {
            "quantity": "20",
            "measure": "ml",
            "ingredient": "Whipping Cream"
        },
        {
            "quantity": "20",
            "measure": "gram",
            "ingredient": "Ice"
        },
        {
            "quantity": "1",
            "measure": "scoop",
            "ingredient": "Coconut Ice Cream (optional)"
        },
        {
            "quantity": "10",
            "measure": "gram",
            "ingredient": "Coconut Flesh (optional)"
        }
    ],
    "directions": [
        "Prepare one shot of espresso. If you can't get espresso, drip brewed coffee works fine but the taste won't be as robust.",
        "Mix the coconut milk, condensed milk, whipping cream, ice together in a blender.",
        "Put the coconut mixture into a glass cup, pour the espresso over.",
        "Garnish with the ice cream scoop or the coconut flesh.",
        "This drink tastes best on a hot day."
    ],
    "image": "coconut-coffee.jpg",
    "keywords": [
        "coffee",
        "coconut",
        "cream",
        "cold",
        "non-alcoholic",
        "organic"
    ]
}

{
    "name": "Iced Matcha Latte",
    "description": "This Iced Matcha Latte is a creamy and refreshing beverage, perfect for a morning or afternoon pick me up",
    "github": "amgcheng",
    "ingredients": [
        {
            "quantity": "2",
            "measure": "teaspoon",
            "ingredient": "Matcha Powder"
        },
        {
            "quantity": "2",
            "measure": "teaspoon",
            "ingredient": "Syrup or Sugar or Honey"
        },
        {
            "quantity": "1",
            "measure": "tablespoon",
            "ingredient": "Hot Water"
        },
        {
            "quantity": "2",
            "measure": "tablespoon",
            "ingredient": "Heavy Cream or Coffee Creamer"
        },
        {
            "quantity": "1",
            "measure": "cup",
            "ingredient": "Ice"
        }
    ],
    "directions": [
        "Place Matcha Powder in small bowl",
        "Add Hot Water and whisk until smooth with no lumps remaining",
        "Place Ice in your glass",
        "Pour Matcha and Water mixture into glass",
        "Add Syrup to taste",
        "Whisk Heavy Cream until frothy and desired thickness",
        "Place whisked Heavy Cream on top",
        "Enjoy with whisked Heavy Cream mixed into drink or sitting on top"
    ],
    "image": "iced-matcha-latte.jpg",
    "keywords": [
        "matcha",
        "latte",
        "non-alcoholic"
    ]
}

