{
    "name": "Sambharam",
    "description": "Sambharam is a traditional spiced buttermilk drink from Kerala, India. It's a refreshing and cooling beverage, especially popular during the hot and humid months. Sambharam is flavored with ginger, green chilies, curry leaves, and salt, making it a perfect drink to beat the heat.",
    "github": "Marvellousz",
    "ingredients": [
        {
            "quantity": "2",
            "measure": "cups",
            "ingredient": "Buttermilk"
        },
        {
            "quantity": "1",
            "measure": "tsp",
            "ingredient": "Grated Ginger"
        },
        {
            "quantity": "2",
            "measure": "",
